'use client';
import React from 'react';

import * as Picker from 'emoji-picker-react/primitives';

// Tabs first, then search: an order the default picker does not offer.
// SkinTone is composed inside Search to share its header and keyboard flow.
export type PickerExampleProps = {
  /** The picker root: Picker.Root, or a styled() wrapper of it. */
  Root?: React.ComponentType<Picker.RootProps>;
  className?: string;
};

export function PickerExample({
  Root: RootComponent = Picker.Root,
  className,
}: PickerExampleProps) {
  return (
    <RootComponent
      appearance="default"
      className={className}
      searchPlaceholder="Search emoji"
    >
      <Picker.CategoryNav />
      <Picker.Search>
        <Picker.SkinTone />
      </Picker.Search>
      <Picker.Viewport>
        <Picker.List />
        <Picker.Empty />
      </Picker.Viewport>
      <Picker.Preview />
    </RootComponent>
  );
}

/* Microsoft Teams (Fluent 2) — compact flyout: Segoe type, 4px radii,
   underlined segmented tabs on top, Teams brand purple. */
/* Picker styles — the source of truth for every stack variant. */
.teams-picker {
  --fluent-brand: #5b5fc7;
  --epr-bg-color: #ffffff;
  --epr-text-color: #242424;
  --epr-highlight-color: var(--fluent-brand);
  --epr-hover-bg-color: #f5f5f5;
  --epr-focus-bg-color: #ebebeb;
  --epr-search-input-bg-color: #ffffff;
  --epr-search-input-bg-color-active: #ffffff;
  --epr-search-border-color: #d1d1d1;
  --epr-search-border-color-active: var(--fluent-brand);
  --epr-search-input-height: 32px;
  --epr-search-input-border-radius: 4px;
  --epr-search-input-padding: 0 10px 0 32px;
  --epr-search-input-text-color: #242424;
  --epr-search-input-placeholder-color: #707070;
  --epr-category-label-bg-color: #fffffff2;
  --epr-category-label-text-color: #424242;
  --epr-category-label-height: 30px;
  --epr-category-icon-active-color: var(--fluent-brand);
  --epr-category-icon-inactive-color: #616161;
  --epr-category-navigation-button-size: 20px;
  --epr-preview-height: 44px;
  --epr-preview-emoji-size: 24px;
  --epr-preview-text-color: #242424;
  --epr-preview-border-color: #e0e0e0;
  --epr-emoji-size: 26px;
  --epr-emoji-padding: 4px;
  --epr-horizontal-padding: 12px;
  width: 352px;
  height: 400px;
  border: 1px solid #e0e0e0;
  border-radius: 8px;
  background: #fff;
  box-shadow:
    0 0 2px rgb(0 0 0 / 12%),
    0 8px 16px rgb(0 0 0 / 14%);
  font-family: 'Segoe UI', 'Segoe UI Web', -apple-system, BlinkMacSystemFont,
    Roboto, sans-serif;
}
.teams-picker [data-epr-part='category-nav'] {
  border-bottom: 1px solid #e0e0e0;
}
.teams-picker [data-epr-part='category-nav'] > * {
  padding: 10px 12px 9px;
}
.teams-picker [data-epr-part='category-tab'][aria-selected='true'] {
  box-shadow: 0 11px 0 -8px var(--fluent-brand);
}
.teams-picker [data-epr-part='search'] > * {
  padding: 10px 12px 4px;
}
.teams-picker [data-epr-part='category-label'] {
  font-size: 12px;
  font-weight: 600;
  text-transform: none;
}
.teams-picker [data-epr-part='emoji'] {
  border-radius: 4px;
}
.teams-picker [data-epr-part='preview'] {
  font-size: 12px;
}

